package Q3;
import java.io.*;import java.nio.file.*;import java.util.*;
public class ReportGenerator{static void generate(List<Path>files,Path out)throws IOException{Path tmp=out.resolveSibling(out.getFileName()+".tmp");try(BufferedWriter w=Files.newBufferedWriter(tmp)){for(Path p:files){try(BufferedReader r=Files.newBufferedReader(p)){String line;while((line=r.readLine())!=null)w.write(line+"\\n");}catch(IOException e){w.write("FAILED: "+p+" : "+e.getMessage()+"\\n");}}}Files.move(tmp,out,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}public static void main(String[]x)throws Exception{Path d=Files.createTempDirectory("sales");Path a=d.resolve("store1.txt"),b=d.resolve("store2.txt");Files.writeString(a,"Sales 100\\n");Files.writeString(b,"Sales 200\\n");Path o=d.resolve("report.txt");generate(List.of(a,b),o);System.out.print(Files.readString(o));}}
